function fmtDate(iso,opts){if(!iso)return'';const d=/^\d{4}-\d{2}-\d{2}$/.test(iso)?new Date(iso+'T12:00:00'):new Date(iso);return isNaN(d)?iso:d.toLocaleDateString(({fr:'fr-FR',en:'en-GB',es:'es-ES',ar:'ar'})[lang()]||'fr-FR',opts||{day:'numeric',month:'long',year:'numeric'});}
